def CH(id,claim,question,date_line,heading,body,wn,vals,bul,note=None,rel="extended",extra=None,changed=None):
    SID="www/about-aws/whats-new/"+wn
    ev=[E(SID,date_line,None,heading),E(SID,body)]
    if extra: ev.append(E(SID,extra))
    return F(id,"change",claim,question,vals,"","",False,"",ev,tier=3,vol="frequently-changing" if not changed else "changed-since-2022",rel=rel,bullets=bul,ci=[chg(wn.split('/',2)[2])],note=note,changed=changed)
